import pandas as pd,numpy as np
R=pathlib.Path(__file__).resolve().parent;S=R/'primary2010/functional';O=R/'threshold_sensitivity';O.mkdir(exist_ok=True)
KEY=['center_id','year','max_distance_km','quality','basis'];GROUP=['year','max_distance_km','quality','basis'];source=S/'sector_profiles.parquet';primary=S/'functional_types.parquet';before={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in [source,primary,S/'FINISHED.json']};p=pd.read_parquet(source,columns=KEY+['n_organizations_zone','share','location_quotient','okved_section']);base=p[KEY+['n_organizations_zone']].drop_duplicates(KEY).rename(columns={'n_organizations_zone':'N_zone'});assert not base.duplicated(KEY).any();old=pd.read_parquet(primary,columns=KEY+['dominant_specialization']);results=[];checks=[]
