for share,lq,label in [(.15,1.1,'relaxed'),(.2,1.25,'primary'),(.25,1.5,'strict')]:
 mask=p.n_organizations_zone.ge(5)&p.share.ge(share)&p.location_quotient.ge(lq)&~p.okved_section.isin(['UNKNOWN','missing','nan']);selected=p.loc[mask].sort_values(KEY+['share','location_quotient','okved_section'],ascending=[True]*len(KEY)+[False,False,True]);best=selected.drop_duplicates(KEY)[KEY+['okved_section']].rename(columns={'okved_section':'dominant_specialization'});n=selected.groupby(KEY).size().rename('n_qualifying_sectors').reset_index();d=base.merge(best,on=KEY,how='left',validate='one_to_one').merge(n,on=KEY,how='left',validate='one_to_one');d['dominant_specialization']=d.dominant_specialization.fillna('no_qualifying_specialization');d.loc[d.N_zone<5,'dominant_specialization']='insufficient_reporters';d['n_qualifying_sectors']=d.n_qualifying_sectors.fillna(0).astype(int);d['share_min']=share;d['LQ_min']=lq;d['threshold_variant']=label
 ck(label+' unique keys',not d.duplicated(KEY).any());ck(label+' group coverage',len(d)==len(base))
 if previous is not None:ck(label+' qualifying subset of relaxed predecessor',not (mask&~previous).any())
 previous=mask
 if label=='primary':
  j=d.merge(old,on=KEY,validate='one_to_one',suffixes=('_recomputed','_saved'));ck('main threshold exactly reproduces all saved classifications',j.dominant_specialization_recomputed.eq(j.dominant_specialization_saved).all());ck('main threshold full match key count',len(j)==len(base))
 d=d.merge(old,on=KEY,validate='one_to_one',suffixes=('','_primary'));d['adequate']=d.N_zone.ge(5);d['agrees_with_primary']=d.dominant_specialization.eq(d.dominant_specialization_primary);results.append(d)
