def save(df,name):
 for ext in ['parquet','csv.gz']:
  dst=O/(name+'.'+ext);tmp=O/(name+'.'+ext+'.tmp')
  if ext=='parquet':df.to_parquet(tmp,index=False);back=pd.read_parquet(tmp)
  else:df.to_csv(tmp,index=False,compression='gzip');back=pd.read_csv(tmp,compression='gzip')
  ck(name+' '+ext+' readback',back.shape==df.shape);os.replace(tmp,dst)
save(alltypes,'threshold_classifications');save(summary,'threshold_sensitivity');summary.to_csv(O/'threshold_sensitivity.csv.tmp',index=False);assert len(pd.read_csv(O/'threshold_sensitivity.csv.tmp'))==len(summary);os.replace(O/'threshold_sensitivity.csv.tmp',O/'threshold_sensitivity.csv')
